//! Differential ratchet for
//! `src/engine/battleScriptTrysetmagiccoatOpcode.ts`. Expected complete
//! projected outputs, typed controls, and the exact missing-attacker error are
//! generated by executing the canonical TypeScript opcode handler; regenerate
//! with `node --experimental-strip-types
//! core-rs/tools/gen-battle-script-trysetmagiccoat-vectors.mjs`.
//!
//! The behavioral source is `Cmd_trysetmagiccoat` in
//! `reference/pokeemerald/src/battle_script_commands.c:9537-9550`; the source
//! bitfields are `include/battle.h:106-111,134-140`, and the source `u8`
//! action/count globals are `include/battle.h:640,645`. These tests retain the
//! canonical TypeScript topology validation from
//! `src/engine/battleScriptRulesContext.ts:1813-1854`, including the source
//! `BATTLE_TYPE_DOUBLE` bit from `include/constants/battle.h:59`.

use std::collections::BTreeSet;

use factory_core::battle_script_trysetmagiccoat::{
    apply_battle_script_trysetmagiccoat, BattleScriptTrysetmagiccoatBattler,
    BattleScriptTrysetmagiccoatBattlerState, BattleScriptTrysetmagiccoatBattlersCount,
    BattleScriptTrysetmagiccoatBit, BattleScriptTrysetmagiccoatControl,
    BattleScriptTrysetmagiccoatOutcome, BattleScriptTrysetmagiccoatRoles,
    BattleScriptTrysetmagiccoatRules, BattleScriptTrysetmagiccoatTopology,
    BATTLE_SCRIPT_TRYSETMAGICCOAT_BATTLERS, BATTLE_SCRIPT_TRYSETMAGICCOAT_BATTLER_COUNT,
    BATTLE_SCRIPT_TRYSETMAGICCOAT_BATTLE_TYPE_DOUBLE,
};
use factory_core::battle_script_trysetmagiccoat_vectors_gen::{
    BattleScriptTrysetmagiccoatVectorCase, BattleScriptTrysetmagiccoatVectorState,
    BATTLE_SCRIPT_TRYSETMAGICCOAT_ATTACKER_DOMAIN,
    BATTLE_SCRIPT_TRYSETMAGICCOAT_BATTLERS_COUNT_DOMAIN,
    BATTLE_SCRIPT_TRYSETMAGICCOAT_BATTLE_TYPE_FLAGS_U32_EDGE_DOMAIN,
    BATTLE_SCRIPT_TRYSETMAGICCOAT_BRANCH_CENSUS, BATTLE_SCRIPT_TRYSETMAGICCOAT_CASES,
    BATTLE_SCRIPT_TRYSETMAGICCOAT_CATEGORY_CENSUS,
    BATTLE_SCRIPT_TRYSETMAGICCOAT_CURRENT_TURN_ACTION_NUMBER_DOMAIN,
    BATTLE_SCRIPT_TRYSETMAGICCOAT_DOMAIN_CENSUS,
    BATTLE_SCRIPT_TRYSETMAGICCOAT_VECTOR_CORPUS_SHA256,
};

fn bit(value: u8) -> BattleScriptTrysetmagiccoatBit {
    match value {
        0 => BattleScriptTrysetmagiccoatBit::Clear,
        1 => BattleScriptTrysetmagiccoatBit::Set,
        _ => panic!("generated bit must be 0 or 1, got {value}"),
    }
}

fn rules(value: BattleScriptTrysetmagiccoatVectorState) -> BattleScriptTrysetmagiccoatRules {
    let battlers_count = BattleScriptTrysetmagiccoatBattlersCount::try_from(value.battlers_count)
        .expect("generated canonical battlersCount");
    BattleScriptTrysetmagiccoatRules {
        battlers: core::array::from_fn(|index| BattleScriptTrysetmagiccoatBattlerState {
            bounce_move: bit(value.bounce_moves[index]),
            pp_not_affected_by_pressure: bit(value.pp_not_affected_by_pressure[index]),
        }),
        topology: BattleScriptTrysetmagiccoatTopology::new(battlers_count, value.battle_type_flags)
            .expect("generated canonical double-flag topology"),
        current_turn_action_number: value.current_turn_action_number,
        selector_roles: BattleScriptTrysetmagiccoatRoles {
            attacker: value.attacker,
            target: value.target,
            effect_battler: value.effect_battler,
            fainted: value.fainted,
        },
    }
}

fn vector_state(value: BattleScriptTrysetmagiccoatRules) -> BattleScriptTrysetmagiccoatVectorState {
    BattleScriptTrysetmagiccoatVectorState {
        bounce_moves: value.battlers.map(|battler| battler.bounce_move.as_u8()),
        pp_not_affected_by_pressure: value
            .battlers
            .map(|battler| battler.pp_not_affected_by_pressure.as_u8()),
        battlers_count: value.topology.battlers_count().as_u8(),
        battle_type_flags: value.topology.battle_type_flags(),
        current_turn_action_number: value.current_turn_action_number,
        attacker: value.selector_roles.attacker,
        target: value.selector_roles.target,
        effect_battler: value.selector_roles.effect_battler,
        fainted: value.selector_roles.fainted,
    }
}

#[test]
fn complete_projected_outputs_controls_exact_error_and_input_preservation_match_canonical_typescript(
) {
    assert_eq!(BATTLE_SCRIPT_TRYSETMAGICCOAT_CASES.len(), 1302);
    for (case_index, case) in BATTLE_SCRIPT_TRYSETMAGICCOAT_CASES.iter().enumerate() {
        execute_case(case_index, case);
    }
}

fn execute_case(case_index: usize, case: &BattleScriptTrysetmagiccoatVectorCase) {
    let input = rules(case.initial);
    let before = input;
    let mut current = input;
    let mut actual_controls = Vec::new();
    let mut actual_error = None;

    for application in 0..case.applications {
        let prior = current;
        match apply_battle_script_trysetmagiccoat(&current) {
            Ok(outcome) => {
                actual_controls.push(outcome.control);
                assert_transition_shape(case_index, case, application, prior, outcome);
                current = outcome.rules;
            }
            Err(error) => {
                actual_error = Some(error.to_string());
                break;
            }
        }
    }

    assert_eq!(
        input, before,
        "case {case_index} {}: native transformation mutated input",
        case.label,
    );
    match (actual_error, case.expected, case.expected_error) {
        (None, Some(expected), None) => {
            assert_eq!(
                actual_controls.as_slice(),
                case.controls,
                "case {case_index} {}: canonical control sequence",
                case.label,
            );
            assert_eq!(
                actual_controls.len(),
                usize::from(case.applications),
                "case {case_index} {}: successful sequence stopped early",
                case.label,
            );
            assert_eq!(
                vector_state(current),
                expected,
                "case {case_index} {}: complete projected output",
                case.label,
            );
        }
        (Some(error), None, Some(expected_error)) => {
            assert_eq!(
                actual_controls.as_slice(),
                case.controls,
                "case {case_index} {}: error must not produce a control result",
                case.label,
            );
            assert_eq!(
                error, expected_error,
                "case {case_index} {}: exact canonical role error",
                case.label,
            );
        }
        (error, expected, expected_error) => panic!(
            "case {case_index} {}: generated outcome shape disagrees with native result: error={error:?}, expected={expected:?}, expected_error={expected_error:?}",
            case.label,
        ),
    }
}

fn assert_transition_shape(
    case_index: usize,
    case: &BattleScriptTrysetmagiccoatVectorCase,
    application: u8,
    prior: BattleScriptTrysetmagiccoatRules,
    outcome: BattleScriptTrysetmagiccoatOutcome,
) {
    let attacker = prior.selector_roles.attacker.unwrap_or_else(|| {
        panic!(
            "case {case_index} {} application {application}: successful result had no attacker",
            case.label,
        )
    });
    let acting_last =
        prior.current_turn_action_number == prior.topology.battlers_count().final_action_number();
    let expected_control = if acting_last {
        BattleScriptTrysetmagiccoatControl::FailJump
    } else {
        BattleScriptTrysetmagiccoatControl::Advance
    };

    assert_eq!(
        outcome.control, expected_control,
        "case {case_index} {} application {application}: source action-index control branch",
        case.label,
    );
    assert_eq!(
        outcome.rules.topology, prior.topology,
        "case {case_index} {} application {application}: changed source topology",
        case.label,
    );
    assert_eq!(
        outcome.rules.current_turn_action_number, prior.current_turn_action_number,
        "case {case_index} {} application {application}: changed source action byte",
        case.label,
    );
    assert_eq!(
        outcome.rules.selector_roles.attacker, prior.selector_roles.attacker,
        "case {case_index} {} application {application}: changed attacker role",
        case.label,
    );
    assert_eq!(
        outcome.rules.selector_roles.target,
        Some(attacker),
        "case {case_index} {} application {application}: did not overwrite target with attacker",
        case.label,
    );
    assert_eq!(
        outcome.rules.selector_roles.effect_battler, prior.selector_roles.effect_battler,
        "case {case_index} {} application {application}: changed effectBattler selector sibling",
        case.label,
    );
    assert_eq!(
        outcome.rules.selector_roles.fainted, prior.selector_roles.fainted,
        "case {case_index} {} application {application}: changed fainted selector sibling",
        case.label,
    );

    for battler in BATTLE_SCRIPT_TRYSETMAGICCOAT_BATTLERS {
        if battler == attacker {
            assert_eq!(
                outcome.rules.battlers[battler.index()].pp_not_affected_by_pressure,
                BattleScriptTrysetmagiccoatBit::Set,
                "case {case_index} {} application {application}: attacker PP was not Pressure-exempt",
                case.label,
            );
            assert_eq!(
                outcome.rules.battlers[battler.index()].bounce_move,
                if acting_last {
                    prior.battlers[battler.index()].bounce_move
                } else {
                    BattleScriptTrysetmagiccoatBit::Set
                },
                "case {case_index} {} application {application}: attacker bounce bit did not preserve/arm",
                case.label,
            );
        } else {
            assert_eq!(
                outcome.rules.battlers[battler.index()],
                prior.battlers[battler.index()],
                "case {case_index} {} application {application}: changed sibling battler {}",
                case.label,
                battler.as_u8(),
            );
        }
    }
}

#[test]
fn valid_singles_doubles_attacker_action_edges_and_complete_u8_action_domain_are_covered() {
    let valid = BATTLE_SCRIPT_TRYSETMAGICCOAT_CASES
        .iter()
        .filter(|case| case.category == "valid-singles-doubles-attacker-action-boundary-matrix")
        .collect::<Vec<_>>();
    assert_eq!(valid.len(), 20);
    let observed_valid = valid
        .iter()
        .map(|case| {
            (
                case.initial.battlers_count,
                case.initial.attacker.expect("valid attacker").as_u8(),
                case.initial.current_turn_action_number,
            )
        })
        .collect::<BTreeSet<_>>();
    let expected_valid = [2_u8, 4]
        .into_iter()
        .flat_map(|battlers_count| {
            (0..battlers_count).flat_map(move |attacker| {
                (0..battlers_count).map(move |current_turn_action_number| {
                    (battlers_count, attacker, current_turn_action_number)
                })
            })
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(observed_valid, expected_valid);
    assert_eq!(
        valid
            .iter()
            .map(|case| case.initial.attacker.expect("valid attacker").as_u8())
            .collect::<BTreeSet<_>>(),
        BATTLE_SCRIPT_TRYSETMAGICCOAT_ATTACKER_DOMAIN
            .into_iter()
            .collect::<BTreeSet<_>>(),
        "all four source battlers must be covered by the valid doubles cells",
    );

    let full_domain = BATTLE_SCRIPT_TRYSETMAGICCOAT_CASES
        .iter()
        .filter(|case| case.category == "current-turn-action-u8-full-domain-by-topology")
        .collect::<Vec<_>>();
    assert_eq!(full_domain.len(), 512);
    for battlers_count in BATTLE_SCRIPT_TRYSETMAGICCOAT_BATTLERS_COUNT_DOMAIN {
        let action_values = full_domain
            .iter()
            .filter(|case| case.initial.battlers_count == battlers_count)
            .map(|case| case.initial.current_turn_action_number)
            .collect::<BTreeSet<_>>();
        assert_eq!(
            action_values,
            BATTLE_SCRIPT_TRYSETMAGICCOAT_CURRENT_TURN_ACTION_NUMBER_DOMAIN
                .into_iter()
                .collect::<BTreeSet<_>>(),
            "battlersCount {battlers_count}: complete u8 action domain",
        );
        for case in full_domain
            .iter()
            .filter(|case| case.initial.battlers_count == battlers_count)
        {
            let expected_control = if case.initial.current_turn_action_number == battlers_count - 1
            {
                BattleScriptTrysetmagiccoatControl::FailJump
            } else {
                BattleScriptTrysetmagiccoatControl::Advance
            };
            assert_eq!(
                case.controls,
                &[expected_control],
                "{}: source equality branch",
                case.label
            );
        }
    }
}

#[test]
fn selector_target_overwrite_and_sibling_domains_are_complete() {
    let selector_cases = BATTLE_SCRIPT_TRYSETMAGICCOAT_CASES
        .iter()
        .filter(|case| case.category == "complete-attacker-target-effect-fainted-selector-matrix")
        .collect::<Vec<_>>();
    assert_eq!(selector_cases.len(), 500);
    let role_value = |value: Option<BattleScriptTrysetmagiccoatBattler>| {
        value.map_or(-1_i8, |battler| battler.as_u8() as i8)
    };
    let observed = selector_cases
        .iter()
        .map(|case| {
            (
                role_value(case.initial.attacker),
                role_value(case.initial.target),
                role_value(case.initial.effect_battler),
                role_value(case.initial.fainted),
            )
        })
        .collect::<BTreeSet<_>>();
    let expected = (0_i8..4)
        .flat_map(|attacker| {
            (-1_i8..4).flat_map(move |target| {
                (-1_i8..4).flat_map(move |effect_battler| {
                    (-1_i8..4).map(move |fainted| (attacker, target, effect_battler, fainted))
                })
            })
        })
        .collect::<BTreeSet<_>>();
    assert_eq!(observed, expected);

    for case in selector_cases {
        let attacker = case.initial.attacker.expect("selector attacker");
        let expected = case.expected.expect("selector expected output");
        assert_eq!(
            expected.target,
            Some(attacker),
            "{}: target overwrite",
            case.label
        );
        assert_eq!(
            expected.attacker, case.initial.attacker,
            "{}: attacker preserved",
            case.label
        );
        assert_eq!(
            expected.effect_battler, case.initial.effect_battler,
            "{}: effectBattler sibling preserved",
            case.label,
        );
        assert_eq!(
            expected.fainted, case.initial.fainted,
            "{}: fainted sibling preserved",
            case.label
        );
    }
}

#[test]
fn complete_prior_bit_matrix_and_u32_topology_flag_edges_are_preserved() {
    let bit_cases = BATTLE_SCRIPT_TRYSETMAGICCOAT_CASES
        .iter()
        .filter(|case| case.category == "complete-per-battler-bounce-and-pp-prior-bit-matrix")
        .collect::<Vec<_>>();
    assert_eq!(bit_cases.len(), 256);
    let packed_bits = |case: &&BattleScriptTrysetmagiccoatVectorCase| {
        let pack = |bits: [u8; 4]| {
            bits.into_iter()
                .enumerate()
                .fold(0_u8, |word, (index, value)| word | (value << index))
        };
        pack(case.initial.bounce_moves) | (pack(case.initial.pp_not_affected_by_pressure) << 4)
    };
    assert_eq!(
        bit_cases.iter().map(packed_bits).collect::<BTreeSet<_>>(),
        (0_u8..=u8::MAX).collect::<BTreeSet<_>>(),
        "all four bounce and all four PP source bit values must be independently covered",
    );

    let flag_cases = BATTLE_SCRIPT_TRYSETMAGICCOAT_CASES
        .iter()
        .filter(|case| case.category == "battle-type-flags-u32-edge-preservation")
        .collect::<Vec<_>>();
    assert_eq!(flag_cases.len(), 8);
    assert_eq!(
        flag_cases
            .iter()
            .map(|case| case.initial.battle_type_flags)
            .collect::<BTreeSet<_>>(),
        BATTLE_SCRIPT_TRYSETMAGICCOAT_BATTLE_TYPE_FLAGS_U32_EDGE_DOMAIN
            .into_iter()
            .collect::<BTreeSet<_>>(),
    );
    for case in flag_cases {
        let expected = case.expected.expect("u32 flag expected output");
        assert_eq!(
            expected.battle_type_flags, case.initial.battle_type_flags,
            "{}: source u32 gBattleTypeFlags word changed",
            case.label,
        );
        assert_eq!(
            (case.initial.battle_type_flags & BATTLE_SCRIPT_TRYSETMAGICCOAT_BATTLE_TYPE_DOUBLE)
                != 0,
            case.initial.battlers_count == 4,
            "{}: generated canonical topology flag pairing",
            case.label,
        );
    }
}

#[test]
fn missing_attacker_alias_and_repeated_application_semantics_are_pinned() {
    let missing = BATTLE_SCRIPT_TRYSETMAGICCOAT_CASES
        .iter()
        .filter(|case| case.category == "ordered-missing-attacker-role-errors")
        .collect::<Vec<_>>();
    assert_eq!(missing.len(), 3);
    for case in missing {
        assert_eq!(
            case.initial.attacker, None,
            "{}: missing attacker input",
            case.label
        );
        assert!(
            case.controls.is_empty(),
            "{}: error must not control",
            case.label
        );
        assert_eq!(
            case.expected_error,
            Some("Battle Script hit-chain command requires a attacker role"),
            "{}: exact canonical error",
            case.label,
        );
    }

    let alias = BATTLE_SCRIPT_TRYSETMAGICCOAT_CASES
        .iter()
        .find(|case| {
            case.label
                == "explicit_attacker_target_alias_preserves_selector_siblings_and_arms_nonlast"
        })
        .expect("explicit alias vector");
    assert_eq!(alias.initial.attacker, alias.initial.target);
    assert_eq!(
        alias.controls,
        &[BattleScriptTrysetmagiccoatControl::Advance]
    );
    let alias_expected = alias.expected.expect("alias expected output");
    assert_eq!(alias_expected.target, alias.initial.attacker);
    assert_eq!(alias_expected.bounce_moves[2], 1);
    assert_eq!(alias_expected.pp_not_affected_by_pressure[2], 1);

    let repeated_nonlast = BATTLE_SCRIPT_TRYSETMAGICCOAT_CASES
        .iter()
        .find(|case| {
            case.label
                == "repeated_nonlast_application_advances_twice_arms_bounce_and_is_value_idempotent"
        })
        .expect("repeated nonlast vector");
    assert_eq!(repeated_nonlast.applications, 2);
    assert_eq!(
        repeated_nonlast.controls,
        &[
            BattleScriptTrysetmagiccoatControl::Advance,
            BattleScriptTrysetmagiccoatControl::Advance,
        ],
    );
    let nonlast_expected = repeated_nonlast.expected.expect("repeated nonlast output");
    assert_eq!(nonlast_expected.target, repeated_nonlast.initial.attacker);
    assert_eq!(nonlast_expected.bounce_moves[2], 1);
    assert_eq!(nonlast_expected.pp_not_affected_by_pressure[2], 1);

    let repeated_last = BATTLE_SCRIPT_TRYSETMAGICCOAT_CASES
        .iter()
        .find(|case| {
            case.label
                == "repeated_acting_last_application_fail_jumps_twice_sets_pp_and_preserves_bounce"
        })
        .expect("repeated acting-last vector");
    assert_eq!(repeated_last.applications, 2);
    assert_eq!(
        repeated_last.controls,
        &[
            BattleScriptTrysetmagiccoatControl::FailJump,
            BattleScriptTrysetmagiccoatControl::FailJump,
        ],
    );
    let last_expected = repeated_last.expected.expect("repeated acting-last output");
    assert_eq!(last_expected.target, repeated_last.initial.attacker);
    assert_eq!(
        last_expected.bounce_moves[1],
        repeated_last.initial.bounce_moves[1]
    );
    assert_eq!(last_expected.pp_not_affected_by_pressure[1], 1);
}

#[test]
fn source_domains_censuses_and_corpus_hash_are_ratchet_pinned() {
    assert_eq!(BATTLE_SCRIPT_TRYSETMAGICCOAT_BATTLER_COUNT, 4);
    assert_eq!(
        BATTLE_SCRIPT_TRYSETMAGICCOAT_BATTLERS.map(|battler| battler.as_u8()),
        BATTLE_SCRIPT_TRYSETMAGICCOAT_ATTACKER_DOMAIN,
    );
    assert_eq!(BATTLE_SCRIPT_TRYSETMAGICCOAT_ATTACKER_DOMAIN, [0, 1, 2, 3]);
    assert_eq!(BATTLE_SCRIPT_TRYSETMAGICCOAT_BATTLERS_COUNT_DOMAIN, [2, 4]);
    assert_eq!(
        BATTLE_SCRIPT_TRYSETMAGICCOAT_CURRENT_TURN_ACTION_NUMBER_DOMAIN,
        core::array::from_fn(|value| value as u8),
    );
    assert_eq!(BATTLE_SCRIPT_TRYSETMAGICCOAT_BATTLE_TYPE_DOUBLE, 1);
    assert_eq!(
        BATTLE_SCRIPT_TRYSETMAGICCOAT_DOMAIN_CENSUS,
        [
            ("battler-slots", 4),
            ("attacker-role-values", 4),
            ("selector-role-values-including-null", 5),
            ("canonical-battlers-count-values", 2),
            ("singles-valid-attacker-values", 2),
            ("doubles-valid-attacker-values", 4),
            ("current-turn-action-number-u8-values", 256),
            ("current-turn-action-u8-full-domain-probes", 512),
            ("valid-reachable-topology-attacker-action-cases", 20),
            ("complete-selector-matrix-cases", 500),
            ("per-battler-bounce-pp-bit-combinations", 256),
            ("battle-type-flags-u32-edge-values", 8),
            ("typed-missing-attacker-role-cases", 3),
            ("application-count-values", 2),
            ("target-role-required-by-handler", 0),
            ("failure-pointer-fields-in-projection", 0),
            ("absolute-program-counter-fields-in-projection", 0),
            ("abi-exports-added", 0),
            ("unsupported-barriers-added", 0),
            ("generated-file-byte-limit-exclusive", 5_000_000),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_TRYSETMAGICCOAT_CATEGORY_CENSUS,
        [
            ("battle-type-flags-u32-edge-preservation", 8),
            (
                "complete-attacker-target-effect-fainted-selector-matrix",
                500
            ),
            ("complete-per-battler-bounce-and-pp-prior-bit-matrix", 256),
            ("current-turn-action-u8-full-domain-by-topology", 512),
            ("explicit-alias-target-overwrite", 1),
            ("ordered-missing-attacker-role-errors", 3),
            ("repeated-acting-last-application", 1),
            ("repeated-nonlast-application", 1),
            ("valid-singles-doubles-attacker-action-boundary-matrix", 20),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_TRYSETMAGICCOAT_BRANCH_CENSUS,
        [
            ("advance", 1032),
            ("advance-then-advance", 1),
            ("fail-jump", 265),
            ("fail-jump-then-fail-jump", 1),
            ("missing-attacker-role", 3),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_TRYSETMAGICCOAT_VECTOR_CORPUS_SHA256,
        "df02734139e4e83d3272769c3a85d99a576395342ee3c9617f626f6a4f439794",
    );
}
